package com.crm.payroll;
import com.crm.payroll.controller.*;import com.crm.payroll.service.*;import com.crm.payroll.dto.PayrollResponse;import java.math.BigDecimal;import org.junit.jupiter.api.*;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class PayrollVariablePdfTest {
 PayrollResponse row(){var r=new PayrollResponse();r.setId(7L);r.setEmployeeId("103");r.setPayPeriod("2026-11");r.setCurrency("TND");r.setBaseSalary(new BigDecimal("100"));r.setNetSalary(new BigDecimal("130.85"));r.setOvertimeHours(new BigDecimal("2.5"));r.setOvertimeHourlyRate(new BigDecimal("12.34"));r.setOvertimeAmount(new BigDecimal("30.85"));r.setPublished(true);r.setCancelled(true);r.setReplacementPayrollId(8L);r.setStatus("PENDING");return r;}
 @AfterEach void clear(){org.springframework.security.core.context.SecurityContextHolder.clearContext();}
 void verifyPdf(byte[] bytes)throws Exception{try(var pdf=Loader.loadPDF(bytes)){String text=new PDFTextStripper().getText(pdf);assertTrue(text.contains("30,85"));assertTrue(text.contains("12,34"));assertTrue(text.contains("130,85"));assertTrue(text.contains("ANNULE - remplace par 8"));assertTrue(text.contains("Heures supplementaires"));}}
 @Test void administratorPdfKeepsStoredVariablesAndCancellation()throws Exception{var service=mock(IPayrollService.class);when(service.getPayrollById(7L)).thenReturn(row());org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(PayrollSettlementPolicyTest.auth("ADMIN"));verifyPdf(new PayrollPdfController(service).download(7L).getBody());}
 @Test void personalPdfUsesAuthorizedRowAndStoredVariables()throws Exception{var service=mock(PersonalPayrollService.class);var auth=PayrollSettlementPolicyTest.auth("EMPLOYEE");when(service.read(auth,"Bearer synthetic",7L)).thenReturn(row());verifyPdf(new PersonalPayrollController(service).pdf(auth,"Bearer synthetic",7L).getBody());verify(service).read(auth,"Bearer synthetic",7L);}
}